const MathGroup* getMathGroup(const QString& id)
{
    for (const auto& group : mathPopupGroups()) {
        if (group.id == id) return &group;
    }
    return nullptr;
}

const MathSymbol* getMathSymbol(const QString& id)
{
    for (const auto& sym : mathQuickAccessSymbols()) {
        if (sym.id == id) return &sym;
    }
    for (const auto& group : mathPopupGroups()) {
        for (const auto& sym : group.symbols) {
            if (sym.id == id) return &sym;
        }
    }
    return nullptr;
}
